<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('teacher');$aid=(int)($_GET['assignment']??$_POST['assignment_id']??0);$uid=(int)$_SESSION['user_id'];$q=$conn->prepare('SELECT a.*,s.section_name,s.grade_level,sub.subject_code,sub.subject_name,y.school_year_name FROM teacher_assignments a JOIN sections s ON s.section_id=a.section_id JOIN subjects sub ON sub.subject_id=a.subject_id JOIN school_years y ON y.school_year_id=a.school_year_id WHERE a.teacher_assignment_id=? AND a.teacher_id=? AND a.status="active"');$q->bind_param('ii',$aid,$uid);$q->execute();$a=$q->get_result()->fetch_assoc();if(!$a){http_response_code(404);exit('Assignment not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){$period=(int)$_POST['period_id'];$q=$conn->prepare('SELECT grading_period_id FROM grading_periods WHERE grading_period_id=? AND school_year_id=? AND status="active"');$q->bind_param('ii',$period,$a['school_year_id']);$q->execute();if(!$q->get_result()->fetch_assoc()){flash('Select an active grading period for this school year.','error');go('?assignment='.$aid);}try{$conn->begin_transaction();foreach(($_POST['grade']??[]) as $sid=>$raw){$sid=(int)$sid;if($raw===''||!is_numeric($raw)||(float)$raw<0||(float)$raw>999.99)continue;$val=(float)$raw;$q=$conn->prepare('SELECT g.grade_id,g.grade_status FROM students st JOIN student_enrollments en ON en.student_id=st.student_id AND en.school_year_id=? AND en.assignment_status="active" JOIN sections sec ON sec.section_id=en.section_id JOIN teacher_assignments ta ON ta.section_id=sec.section_id AND ta.teacher_assignment_id=? WHERE st.student_id=?');$q->bind_param('iii',$a['school_year_id'],$aid,$sid);$q->execute();if(!$q->get_result()->fetch_assoc())continue;$q=$conn->prepare('SELECT grade_status FROM grades WHERE student_id=? AND teacher_assignment_id=? AND grading_period_id=?');$q->bind_param('iii',$sid,$aid,$period);$q->execute();$old=$q->get_result()->fetch_assoc();if($old&&in_array($old['grade_status'],['submitted','approved','finalized','released'],true))continue;$draft='draft';$q=$conn->prepare('INSERT INTO grades(student_id,teacher_assignment_id,grading_period_id,grade_value,grade_status) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE grade_value=VALUES(grade_value),grade_status="draft",updated_at=NOW()');$q->bind_param('iiids',$sid,$aid,$period,$val,$draft);$q->execute();audit($conn,$uid,'grade_draft_saved','grade',null,['student_id'=>$sid,'assignment_id'=>$aid,'period_id'=>$period]);}if(isset($_POST['submit_grades'])){$q=$conn->prepare('UPDATE grades SET grade_status="submitted",submitted_at=NOW() WHERE teacher_assignment_id=? AND grading_period_id=? AND grade_status="draft"');$q->bind_param('ii',$aid,$period);$q->execute();audit($conn,$uid,'grades_submitted','teacher_assignment',$aid,['period_id'=>$period]);}$conn->commit();flash('Grade changes saved.');}catch(Throwable $e){$conn->rollback();flash('Grades could not be saved.','error');}go('?assignment='.$aid.'&period='.$period);}
$q=$conn->prepare('SELECT * FROM grading_periods WHERE school_year_id=? AND status="active" ORDER BY period_order');$q->bind_param('i',$a['school_year_id']);$q->execute();$periods=$q->get_result()->fetch_all(MYSQLI_ASSOC);$period=(int)($_GET['period']??($periods[0]['grading_period_id']??0));$q=$conn->prepare('SELECT st.student_id,st.lrn,st.firstname,st.middle_name,st.lastname,g.grade_value,g.grade_status FROM students st JOIN student_enrollments en ON en.student_id=st.student_id AND en.school_year_id=? AND en.section_id=? AND en.assignment_status="active" LEFT JOIN grades g ON g.student_id=st.student_id AND g.teacher_assignment_id=? AND g.grading_period_id=? WHERE st.record_status="active" ORDER BY st.lastname,st.firstname');$q->bind_param('iiii',$a['school_year_id'],$a['section_id'],$aid,$period);$q->execute();$rows=$q->get_result();page_start('Gradebook');echo '<h1>Gradebook</h1><p>'.e($a['school_year_name'].' · Grade '.$a['grade_level'].' · '.$a['section_name'].' · '.$a['subject_code'].' — '.$a['subject_name']).'</p><form method="get"><input type="hidden" name="assignment" value="'.$aid.'"><label>Grading period<select name="period" onchange="this.form.submit()">';foreach($periods as $p)echo '<option value="'.$p['grading_period_id'].'" '.($period===(int)$p['grading_period_id']?'selected':'').'>'.e($p['period_name']).'</option>';echo '</select></label></form><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="assignment_id" value="'.$aid.'"><input type="hidden" name="period_id" value="'.$period.'"><div class="tablewrap"><table><tr><th>LRN</th><th>Student</th><th>Grade value</th><th>Status</th></tr>';while($s=$rows->fetch_assoc()){echo '<tr><td>'.e($s['lrn']).'</td><td>'.e(trim($s['lastname'].', '.$s['firstname'].' '.$s['middle_name'])).'</td><td><input aria-label="Grade for '.e($s['firstname']).'" name="grade['.(int)$s['student_id'].']" type="number" step="0.01" min="0" max="999.99" value="'.e($s['grade_value']===null?'':(string)$s['grade_value']).'" '.(in_array($s['grade_status'],['submitted','approved','finalized','released'],true)?'disabled':'').'></td><td>'.e($s['grade_status']??'—').'</td></tr>'; }echo '</table></div><p>Grade values are recorded as entered. Configure the approved grading scale and calculation rules before production use.</p><button name="save" value="1">Save drafts</button> <button name="submit_grades" value="1">Submit period grades for review</button></form>';page_end();
